211	function summarizeScanResult(scan: ScanResult | null) {
212	  if (!scan) return '';
213	  const libraryEntries = (Object.entries(scan.aiLibraryMatches ?? {}) as Array<[string, number]>).sort(
214	    (a, b) => b[1] - a[1]
215	  );
216	  const functionEntries = (Object.entries(scan.aiFunctionMatches ?? {}) as Array<[string, number]>).sort(
217	    (a, b) => b[1] - a[1]
218	  );
219	  const libraries = libraryEntries.slice(0, 5).map(([name, count]) => `${name} (${count})`).join(', ');
220	  const functions = functionEntries.slice(0, 5).map(([name, count]) => `${name} (${count})`).join(', ');
221	
222	  return [
223	    `Detected ${scan.aiFiles.length} AI related files out of ${scan.totalFiles} scanned.`,
224	    libraries ? `Top libraries: ${libraries}` : 'No AI libraries detected.',
225	    functions ? `Top functions: ${functions}` : 'No AI-specific functions detected.'
226	  ].join('\n');
227	}
