499	function runRagIndexCommand(options: RagOptions) {
500	  const payload = (Rag.indexDocuments as unknown as (config: unknown) => any)({
501	    input: options.input,
502	    output: options.output,
503	    chunkSize: options.chunkSize,
504	    extensions: options.extensions
505	  });
506	  log.success('RAG index created.', {
507	    documentCount: payload.metadata.documentCount,
508	    entryCount: payload.metadata.entryCount,
509	    output: options.output ?? 'frai-index.json'
