74	async function cmdInit(args: Args): Promise<number> {
75	  const out = typeof args.flags.get('out') === 'string' ? (args.flags.get('out') as string) : 'FRAI-SPEC.md';
76	  const target = path.resolve(process.cwd(), out);
77	  try {
