117	  } else if (args.flags.has('smart') && !result.gateSection) {
118	    console.error('Skipping smart review: no gate section to review.');
119	  }
120	
121	  console.log(args.flags.has('json') ? renderJson(result, specPath) : renderText(result, specPath));
122	  return result.verdict === 'BLOCK' ? 1 : 0;
123	}
124	
125	async function cmdDraft(args: Args): Promise<number> {
126	  const section = await draftGateSection(process.cwd());
127	  if (args.flags.has('print')) {
128	    console.log(section);
129	    return 0;
130	  }
131	  const out = typeof args.flags.get('out') === 'string' ? (args.flags.get('out') as string) : 'rai-gate-draft.md';
132	  await fs.writeFile(path.resolve(process.cwd(), out), `${section}\n`);
