134	  console.log('Review it, resolve every "NEEDS HUMAN INPUT" item, paste it into your spec, then run: frai-gate check <spec.md>');
135	  return 0;
136	}
137	
138	async function main(): Promise<void> {
139	  const args = parseArgs(process.argv.slice(2));
140	  let code = 0;
141	  switch (args.command) {
142	    case 'init':
143	      code = await cmdInit(args);
144	      break;
145	    case 'check':
146	      code = await cmdCheck(args);
147	      break;
148	    case 'draft':
149	      code = await cmdDraft(args);
150	      break;
151	    case undefined:
152	    case 'help':
153	    case '--help':
154	      console.log(HELP);
155	      break;
156	    default:
157	      console.error(`Unknown command: ${args.command}\n`);
158	      console.log(HELP);
159	      code = 2;
160	  }
161	  process.exitCode = code;
162	}
163	
164	main().catch((error: unknown) => {
