52	function parseArgs(argv: string[]): Args {
53	  const [command, ...rest] = argv;
54	  const positional: string[] = [];
55	  const flags = new Map<string, string | true>();
56	  for (let i = 0; i < rest.length; i += 1) {
57	    const arg = rest[i];
58	    if (arg.startsWith('--')) {
59	      const name = arg.slice(2);
60	      const next = rest[i + 1];
61	      if (next !== undefined && !next.startsWith('--') && ['out', 'spec'].includes(name)) {
62	        flags.set(name, next);
63	        i += 1;
64	      } else {
65	        flags.set(name, true);
66	      }
67	    } else {
68	      positional.push(arg);
69	    }
70	  }
71	  return { command, positional, flags };
72	}
