  .action(async (args: string[], options: Record<string, unknown>) => {
    const require = createRequire(import.meta.url);
    let gateCli: string;
    try {
      const gatePkg = require.resolve('frai-gate/package.json');
      gateCli = path.join(path.dirname(gatePkg), 'dist', 'cli.js');
    } catch {
      log.error('frai-gate is not installed. Run: npm install -g frai-gate');
      process.exit(2);
    }
    const { spawnSync } = await import('child_process');
    const flags = convertOptionsToFlags(options);
    const fullArgs = [gateCli, ...(args ?? []), ...flags];
    console.error('DEBUG: args=', args, 'options=', options, 'flags=', flags, 'fullArgs=', fullArgs);
    const result = spawnSync(process.execPath, fullArgs, { stdio: 'inherit' });
    process.exit(result.status ?? 0);
  });

